#include <juce_audio_utils/juce_audio_utils.h>
#include "ZAAudioImportRecipe.h"
#include <iostream>
#include <fstream>
#include <stdexcept>
using namespace za::fileimport;
namespace za::fileimport {struct ImportPreviewTestAccess{
    static void capture(ImportPreviewComponent&c,juce::File out){for(int n=0;n<1200&&c.loading;++n)juce::MessageManager::getInstance()->runDispatchLoopUntil(10);if(!c.source||c.loading)throw std::runtime_error("Material preview failed");auto stream=out.createOutputStream();if(stream){stream->setPosition(0);stream->truncate();}if(!stream||!juce::PNGImageFormat().writeImageToStream(c.createComponentSnapshot(c.getLocalBounds()),*stream))throw std::runtime_error("Screenshot failed");c.waveform.fitSelection(c.previewSegments.front().startSample,c.previewSegments.front().endSample);}
};}
static void saveWave(juce::AudioBuffer<float>&b,juce::File f){f.deleteFile();auto stream=f.createOutputStream();juce::WavAudioFormat fmt;std::unique_ptr<juce::AudioFormatWriter>w(fmt.createWriterFor(stream.release(),48000,2,24,{},0));if(!w||!w->writeFromAudioSampleBuffer(b,0,b.getNumSamples()))throw std::runtime_error("WAV write failed");}
int main(int argc,char**argv)try{
    if(argc!=3)throw std::runtime_error("Pass material and output folders");juce::ScopedJuceInitialiser_GUI juce;juce::File folder(argv[1]),out(argv[2]);out.createDirectory();auto files=folder.findChildFiles(juce::File::findFiles,false,"*.wav");files.sort();if(files.size()<4)throw std::runtime_error("Material not found");
    juce::Array<juce::var> rows;std::vector<juce::AudioBuffer<float>> clips;std::vector<int> gaps;int length=24000;
    for(const auto&file:files){juce::String error;auto source=readAudioFile(file,2,48000,0,error);if(!source)throw std::runtime_error(error.toStdString());auto&b=source->buffer;auto audio=audioView(b,48000);auto features=extractor::analyse(audio);extractor::Settings settings;auto t0=juce::Time::getMillisecondCounterHiRes();auto old=extractor::detect(features,settings);auto t1=juce::Time::getMillisecondCounterHiRes();auto now=extractor::detectAdaptive(audio,features,settings);auto t2=juce::Time::getMillisecondCounterHiRes();int end=0;for(const auto&r:now.regions){if(r.start<end||r.end<=r.start||r.end>b.getNumSamples())throw std::runtime_error("Invalid material boundaries");end=r.end;}auto row=juce::var(new juce::DynamicObject());auto*d=row.getDynamicObject();d->setProperty("file",file.getFileName());d->setProperty("seconds",b.getNumSamples()/48000.);d->setProperty("original_regions",int(old.regions.size()));d->setProperty("adaptive_regions",int(now.regions.size()));d->setProperty("original_ms",t1-t0);d->setProperty("adaptive_ms",t2-t1);rows.add(row);length+=b.getNumSamples()+24000;clips.push_back(std::move(b));}
    juce::AudioBuffer<float> joined(2,length);joined.clear();int pos=24000;for(auto&b:clips){for(int ch=0;ch<2;++ch)joined.copyFrom(ch,pos,b,ch,0,b.getNumSamples());pos+=b.getNumSamples();gaps.push_back(pos);pos+=24000;}
    auto features=extractor::analyse(audioView(joined,48000));auto now=extractor::detectAdaptive(audioView(joined,48000),features,{});for(int gap:gaps)for(const auto&r:now.regions)if(r.start<gap+6000&&r.end>gap+18000)throw std::runtime_error("Boundary stretched across a known half-second gap");
    out.getChildFile("material-results.json").replaceWithText(juce::JSON::toString(juce::var(rows)));auto wave=out.getChildFile("joined-material.wav");saveWave(joined,wave);auto rules=makeDefaultRulesForAction(ImportAction::SegmentLongFile);ImportPreviewComponent c({wave},ImportAction::SegmentLongFile,rules,[](ImportRules){},[](juce::AudioBuffer<float>,double){},[]{},[](bool){});c.addToDesktop(juce::ComponentPeer::windowHasTitleBar);c.setTopLeftPosition(-16000,-16000);c.setVisible(true);ImportPreviewTestAccess::capture(c,out.getChildFile("05-your-material.png"));std::cout<<"PASS "<<files.size()<<" real files: bounded/non-overlapping regions; no crossing of "<<gaps.size()<<" known gaps. No hand-labelled event accuracy claim. Joined duration "<<length/48000.<<" s; proposals "<<now.regions.size()<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
